	}
	resolved := forge.User{
		ID:       fmt.Sprint(user.ID),
		Username: user.Username,
		Name:     user.Name,
	}

	f.mu.Lock()
	f.user = &resolved
	f.mu.Unlock()
	return resolved, nil
}""")
